-- Self-checking tests for identikit 18.1.2: Signed FIR filter.
-- Each case instantiates only this identikit. Models use sampled inputs.
-- Family stimulus/reference variables may be shared; only this DUT is checked.
-- Functional RTL verification does not model analog metastability or routing.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity tb_signed_fir_filter is end entity;
architecture test of tb_signed_fir_filter is
    function sl(b:boolean) return std_logic is
    begin
        if b then
            return '1';
        else
            return '0';
        end if;
    end;
    function vec(n,w:natural) return std_logic_vector is
    begin
        return std_logic_vector(to_unsigned(n,w));
    end;
    function ref_count_width(n:positive) return positive is
        variable bits:positive:=1;
        variable value:natural:=n;
    begin
        while value>1 loop
            bits:=bits+1;
            value:=value/2;
        end loop;
        return bits;
    end;
    signal finished: boolean_vector(0 to 6) := (others => false);
begin
    case_0: block
        signal clk:std_logic:='0';
        signal rst,ce:std_logic:='0';
        signal valid:std_logic;
        signal din:signed(0 downto 0):=(others=>'0');
        signal dout:signed(2 downto 0);
    begin
        clk<=not clk after 5 ns;
        dut:entity work.signed_fir_filter generic map(1,2,(0=>1)) port map(clk,rst,ce,din,dout,valid);
